with c as (
 select id from public.academy_courses where id='meteorology-forecasting-foundations'
), ch as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'الأرصاد القطبية والغلاف الجليدي','دراسة الغطاء الثلجي والجليد البحري والأنهار الجليدية والتربة الصقيعية والدوران الجوي والمناخ القطبي وطرق الرصد والتقييم.',46,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id
), u1 as (
 insert into public.academy_units(chapter_id,title,sort_order,published)
 select id,'الغلاف الجليدي والثلوج',1,false from ch
 on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id
), u2 as (
 insert into public.academy_units(chapter_id,title,sort_order,published)
 select id,'الأرصاد القطبية وتغير المناخ',2,false from ch
 on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id
), d(slug,title,summary,content,ord,mins,objectives,unit_title) as (
 values
('polar-cryosphere-processes','الغلاف الجليدي وعملياته','مكونات الغلاف الجليدي ودوره في توازن الطاقة والماء','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"الغلاف الجليدي يشمل الثلوج الموسمية والأنهار الجليدية والصفائح الجليدية والجليد البحري والتربة الصقيعية. تتغير هذه المكونات عبر التراكم والانصهار والتجمد والتسامي والجريان، ولكل منها زمن استجابة مختلف."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع الغلاف الجليدي وعملياته على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: ارسم مخططاً يربط مكونات الغلاف الجليدي بتبادل الطاقة والماء، ثم حدد متغير رصد مناسباً لكل مكوّن. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع الغلاف الجليدي وعملياته، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"ارسم مخططاً يربط مكونات الغلاف الجليدي بتبادل الطاقة والماء، ثم حدد متغير رصد مناسباً لكل مكوّن."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم الغلاف الجليدي وعملياته وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5560,60,'["شرح المفاهيم الأساسية في الغلاف الجليدي وعملياته","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('snow-cover-monitoring-products','رصد الغطاء الثلجي ومنتجاته','قياس مساحة الثلج وعمقه ومكافئه المائي','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"يراقب الغطاء الثلجي بالمحطات الأرضية والاستشعار عن بعد. تشمل المنتجات مساحة الغطاء ونسبة الثلج وعمقه وخصائصه الطيفية، ويجب الانتباه إلى السحب والغابات والتضاريس والخلط بين الثلج والسحب."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع رصد الغطاء الثلجي ومنتجاته على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: قارن خريطة مساحة الثلج مع قياسات محطات جبلية، وحدد أسباب الاختلاف المكاني. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع رصد الغطاء الثلجي ومنتجاته، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"قارن خريطة مساحة الثلج مع قياسات محطات جبلية، وحدد أسباب الاختلاف المكاني."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم رصد الغطاء الثلجي ومنتجاته وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5570,60,'["شرح المفاهيم الأساسية في رصد الغطاء الثلجي ومنتجاته","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('snow-water-equivalent-estimation','تقدير مكافئ الماء الثلجي','العلاقة بين عمق الثلج وكثافته ومحتواه المائي','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"مكافئ الماء الثلجي SWE هو عمق الماء الناتج عن انصهار الغطاء الثلجي. يقدّر تقريباً من حاصل ضرب عمق الثلج في كثافته النسبية إلى كثافة الماء، مع ضرورة تمثيل التباين المكاني والانضغاط."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع تقدير مكافئ الماء الثلجي على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: إذا كان عمق الثلج 0.8 متر وكثافته 300 كغ/م³، احسب SWE بالمتر ثم بالملليمتر وفسر النتيجة. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع تقدير مكافئ الماء الثلجي، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"إذا كان عمق الثلج 0.8 متر وكثافته 300 كغ/م³، احسب SWE بالمتر ثم بالملليمتر وفسر النتيجة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم تقدير مكافئ الماء الثلجي وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5580,60,'["شرح المفاهيم الأساسية في تقدير مكافئ الماء الثلجي","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('snowpack-energy-budget','ميزانية الطاقة في الغطاء الثلجي','الإشعاع والتدفق الحراري والحرارة الكامنة','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"تحدد ميزانية الطاقة معدل تسخين الثلج أو تبريده وانصهاره. تشمل المكونات الإشعاع القصير والطويل الموجة والتدفقات المحسوسة والكامنة وحرارة المطر والتوصيل داخل الغطاء."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع ميزانية الطاقة في الغطاء الثلجي على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: حلل كيف يؤدي انخفاض البياض وارتفاع الإشعاع الممتص إلى تسريع الانصهار، مع ذكر عاملين قد يعاكسان ذلك. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع ميزانية الطاقة في الغطاء الثلجي، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"حلل كيف يؤدي انخفاض البياض وارتفاع الإشعاع الممتص إلى تسريع الانصهار، مع ذكر عاملين قد يعاكسان ذلك."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم ميزانية الطاقة في الغطاء الثلجي وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5590,60,'["شرح المفاهيم الأساسية في ميزانية الطاقة في الغطاء الثلجي","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('glacier-mass-balance','ميزانية كتلة الأنهار الجليدية','التراكم والاقتطاع وتغير الكتلة','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"ميزانية الكتلة هي الفرق بين تراكم الثلج والاقتطاع بالانصهار والتسامي والانفصال الجليدي. تقاس ميدانياً على خطوط الارتفاع أو باستخدام تغير الارتفاع والمساحة والكتلة من الأقمار الصناعية."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع ميزانية كتلة الأنهار الجليدية على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: فسر معنى ميزانية كتلة سنوية سالبة، واقترح طريقتين مستقلتين للتحقق من اتجاه التغير. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع ميزانية كتلة الأنهار الجليدية، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"فسر معنى ميزانية كتلة سنوية سالبة، واقترح طريقتين مستقلتين للتحقق من اتجاه التغير."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم ميزانية كتلة الأنهار الجليدية وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5600,60,'["شرح المفاهيم الأساسية في ميزانية كتلة الأنهار الجليدية","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('permafrost-active-layer','التربة الصقيعية والطبقة النشطة','التجمد طويل الأمد والذوبان الموسمي','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"التربة الصقيعية أرض تبقى عند أو دون الصفر المئوي لمدة سنتين متتاليتين على الأقل، بينما تنصهر الطبقة النشطة موسمياً فوقها. تؤثر الحرارة والرطوبة والغطاء النباتي والثلج في عمق الذوبان."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع التربة الصقيعية والطبقة النشطة على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: صمم سلسلة رصد سنوية لحرارة التربة وعمق الطبقة النشطة، وحدد لماذا لا تكفي قراءة سطحية واحدة. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع التربة الصقيعية والطبقة النشطة، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"صمم سلسلة رصد سنوية لحرارة التربة وعمق الطبقة النشطة، وحدد لماذا لا تكفي قراءة سطحية واحدة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم التربة الصقيعية والطبقة النشطة وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5610,60,'["شرح المفاهيم الأساسية في التربة الصقيعية والطبقة النشطة","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
('sea-ice-observation-classification','رصد الجليد البحري وتصنيفه','الامتداد والتركيز والعمر والسماكة','{"blocks":[{"type":"heading","text":"مقدمة ومفهوم أساسي"},{"type":"text","text":"يوصف الجليد البحري بالامتداد والتركيز والسماكة والعمر والحركة. تستخدم قياسات الأقمار الصناعية والرادار والعوامات والسفن، وتختلف دلالة كل منتج بحسب الدقة المكانية والخوارزمية."},{"type":"heading","text":"الإطار العلمي"},{"type":"text","text":"يعتمد تحليل موضوع رصد الجليد البحري وتصنيفه على تحديد المتغيرات الأساسية ومجالاتها ووحداتها، ثم فهم العمليات الفيزيائية التي تربط بينها. يجب التمييز بين القياس المباشر والمؤشر المستنتج والمنتج المحسوب، وعدم تفسير أي قيمة خارج سياقها المكاني والزمني."},{"type":"heading","text":"منهجية الرصد والتحليل"},{"type":"list","items":["تحديد السؤال العلمي والفترة والمنطقة ومقياس التحليل.","اختيار مصادر الرصد المناسبة وفحص الدقة والمعايرة والتغطية.","مراجعة القيم المفقودة والقيم الشاذة والاتساق بين الوحدات.","مقارنة أكثر من مصدر مستقل متى أمكن وتوثيق الفروق.","عرض النتائج مع بيان الافتراضات وحدود الاستنتاج."]},{"type":"heading","text":"التفسير والتطبيق"},{"type":"text","text":"في التطبيق العملي: اشرح الفرق بين امتداد الجليد وتركيزه، ولماذا لا يمثلان الكمية نفسها. تسجل البيانات الأصلية ووقت الحصول عليها وإصدار المنتج وخطوات المعالجة حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"example","title":"مثال تحليلي","text":"تُجمع سلسلة زمنية للمتغير المرتبط بموضوع رصد الجليد البحري وتصنيفه، ثم تحسب المتوسطات والانحرافات والاتجاهات بعد فحص جودة البيانات. تقارن النتائج بين المواقع أو الفصول، ويبحث عن تفسير فيزيائي متسق دون اعتبار الارتباط وحده دليلاً على السببية."},{"type":"heading","text":"مصادر الخطأ وعدم اليقين"},{"type":"text","text":"تشمل مصادر عدم اليقين محدودية التغطية، وأخطاء الأجهزة، وتغير الخوارزميات، وعدم تمثيل التضاريس أو السطح، والتباين الطبيعي. يجب فصل عدم اليقين الرصدي عن عدم اليقين الناتج عن المعالجة أو النموذج."},{"type":"callout","text":"قاعدة مهنية: لا تعرض نتيجة قطبية من دون ذكر المصدر والفترة والدقة المكانية وطريقة المعالجة وحدود التفسير."},{"type":"heading","text":"مهمة تطبيقية"},{"type":"text","text":"اشرح الفرق بين امتداد الجليد وتركيزه، ولماذا لا يمثلان الكمية نفسها."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يركز هذا الدرس على فهم رصد الجليد البحري وتصنيفه وربط المفاهيم الفيزيائية بالرصد والتحقق والتفسير. جودة الاستنتاج تعتمد على جودة البيانات ووضوح المنهج وتوثيق عدم اليقين."}]}'::jsonb,5620,60,'["شرح المفاهيم الأساسية في رصد الجليد البحري وتصنيفه","اختيار بيانات وطرق رصد مناسبة للموضوع","تحليل النتائج وتحديد مصادر عدم اليقين"]'::jsonb,'الغلاف الجليدي والثلوج'),
